// ● ajax request
/**
 * Represents a WebDesk Ajax request.
 * @property {string} Id Optional request id.
 * @property {string} OperationName Required operation name.
 * @property {object} Params Optional request parameters.
 * @property {string} Type Request type. Usually Ui or Proc.
 * @property {boolean} IsSingleInstance True when the requested UI may have a single client instance.
 * @property {string} CommandId Optional command id that caused this request.
 * @property {string} CommandName Optional command name that caused this request.
 */
tp.AjaxRequest = class {

    // ● constructor
    /**
     * Creates a WebDesk Ajax request.
     * @param {string} OperationName The operation name.
     * @param {object|null|undefined} Params Optional parameters.
     */
    constructor(OperationName, Params = null) {
        tp.AjaxRequest.Counter++;

        this.Id = tp.AjaxRequest.Counter.toString();
        this.OperationName = OperationName || "";
        this.Params = Params || {};
    }

    // ● static
    /**
     * Ajax request id counter.
     * @type {number}
     */
    static Counter = 0;
    /**
     * Executes an Ajax request and returns the response packet.
     * @param {tp.AjaxRequest|object|string} RequestOrOperationName The request, request-like object, or operation name.
     * @param {object|null|undefined} Params Optional parameters when the first argument is an operation name.
     * @returns {Promise<object|null>} Returns the packet.
     */
    static async Execute(RequestOrOperationName, Params = null) {
        var Request = null;
        var Args;

        if (tp.IsString(RequestOrOperationName)) {
            Request = new tp.AjaxRequest(RequestOrOperationName, Params);
        } else if (tp.IsObject(RequestOrOperationName) && !tp.IsBlankString(RequestOrOperationName.OperationName)) {
            Request = RequestOrOperationName;
        } else {
            tp.Throw("Cannot execute Ajax request. Invalid parameters.");
        }

        Args = await tp.Ajax.PostModelAsync(tp.Urls.AjaxExecute, Request);
        return Args.Packet;
    }
    /**
     * Executes an Ajax request and returns the response packet.
     * @param {tp.AjaxRequest|object|string} RequestOrOperationName The request, request-like object, or operation name.
     * @param {object|null|undefined} Params Optional parameters when the first argument is an operation name.
     * @returns {Promise<object|null>} Returns the packet.
     */
    static async ExecuteAsync(RequestOrOperationName, Params = null) {
        return tp.AjaxRequest.Execute(RequestOrOperationName, Params);
    }    
    
    // ● public
    /**
     * Optional request id.
     * @type {string}
     */
    Id = "";
    /**
     * Required operation name.
     * @type {string}
     */
    OperationName = "";
    /**
     * Optional request parameters.
     * @type {object}
     */
    Params = {};
    /**
     * Request type. Usually Ui or Proc.
     * @type {string}
     */
    Type = "Ui";
    /**
     * True when the requested UI may have a single client instance.
     * @type {boolean}
     */
    IsSingleInstance = false;
    /**
     * Optional command id that caused this request.
     * @type {string}
     */
    CommandId = "";
    /**
     * Optional command name that caused this request.
     * @type {string}
     */
    CommandName = "";
};

// ● 90-command.js
// ● command
/**
 * Represents a named application command.
 */
tp.Command = class extends tp.Def {
    // ● constructor
    /**
     * Creates a command.
     * @param {object|string|null|undefined} Source Optional source command or command name.
     */
    constructor(Source = null) {
        super();
        this.Commands = new tp.DefList(tp.Command);

        if (tp.IsString(Source))
            this.Name = Source;
        else if (tp.IsObject(Source))
            this.Assign(Source);
    }

    // ● public
    /**
     * Assigns values from a source object.
     * @param {object|null|undefined} Source The source object.
     * @returns {void}
     */
    Assign(Source) {
        if (tp.IsNil(Source))
            return;

        super.Assign(Source);

        this.ImageFileName = Source.ImageFileName || "";
        this.Form = Source.Form || "";
        this.Type = Source.Type || "";
        this.IsToggle = Source.IsToggle === true;
        this.IsSingleInstance = Source.IsSingleInstance === true;

        this.Commands.Clear();
        if (tp.IsArray(Source.Commands))
            this.Commands.AddRange(Source.Commands);
        else if (tp.IsArray(Source.Children))
            this.Commands.AddRange(Source.Children);
    }
    /**
     * Adds a child command.
     * @param {object|string|tp.Command} Source The source command.
     * @returns {tp.Command} Returns the added command.
     */
    Add(Source) {
        return this.Commands.Add(Source);
    }
    /**
     * Adds a range of child commands.
     * @param {Array<object|string|tp.Command>|null|undefined} Commands The source commands.
     * @returns {void}
     */
    AddRange(Commands) {
        this.Commands.AddRange(Commands);
    }
    /**
     * Returns true when this command opens a UI form.
     * @returns {boolean} Returns true when this command opens a UI form.
     */
    IsUiCommand() {
        return !tp.IsBlankString(this.Form);
    }
    /**
     * Creates an Ajax request from this command.
     * @returns {tp.AjaxRequest} Returns the Ajax request.
     */
    ToAjaxRequest() {
        var Params = {};
        var Result;

        if (tp.IsObject(this.Params))
            tp.MergePropsShallow(Params, this.Params);

        if (!tp.IsBlankString(this.Form))
            Params.Form = this.Form;

        Result = new tp.AjaxRequest(this.Name, Params);
        Result.Type = !tp.IsBlankString(this.Type) ? this.Type : "Ui";
        Result.IsSingleInstance = this.IsSingleInstance === true;
        Result.CommandId = this.Name;
        Result.CommandName = this.Name;
        return Result;
    }
    /**
     * Returns a JSON-friendly object.
     * @returns {object} Returns a JSON-friendly object.
     */
    toJSON() {
        return {
            Name: this.Name,
            TitleKey: this.TitleKey,
            Title: this.Title,
            ImageFileName: this.ImageFileName,
            Form: this.Form,
            Type: this.Type,
            IsToggle: this.IsToggle,
            IsSingleInstance: this.IsSingleInstance,
            Params: this.Params,
            Commands: this.Commands.Items
        };
    }

    // ● public
    /**
     * The image file name used when this command is displayed.
     * @type {string}
     */
    ImageFileName = "";
    /**
     * The registered form opened by this command.
     * @type {string}
     */
    Form = "";
    /**
     * The command type.
     * @type {string}
     */
    Type = "";
    /**
     * True when this command toggles a boolean value.
     * @type {boolean}
     */
    IsToggle = false;
    /**
     * True when this command should open a single UI instance.
     * @type {boolean}
     */
    IsSingleInstance = false;
    /**
     * Child commands.
     * @type {tp.DefList}
     */
    Commands = null;

    // ● properties
    /**
     * Gets true when this command contains child commands.
     * @returns {boolean} Returns true when this command contains child commands.
     */
    get HasChildren() {
        return this.Commands !== null && this.Commands.Count > 0;
    }
    /**
     * Gets child commands.
     * @returns {tp.DefList} Returns child commands.
     */
    get Children() {
        return this.Commands;
    }
};

/**
 * Creates and returns an Ajax request based on a command.
 * @param {tp.Command} Command The command.
 * @returns {tp.AjaxRequest} Returns the Ajax request.
 */
tp.AjaxRequest.CreateFromCommand = function (Command) {
    if (!(Command instanceof tp.Command))
        Command = new tp.Command(Command);
    return Command.ToAjaxRequest();
};

// ● 1000-init.js
// ● initialization
/**
 * Initializes the Tripous JavaScript runtime.
 * @returns {void}
 */
(function () {
    /**
     * Executes Tripous JavaScript runtime initialization.
     * @returns {void}
     */
    var Initialize = function () {
        var List;
        var Listener;
        var Index;
        if (tp.IsReady === true)
            return;
        tp.IsReady = true;
        if (tp.IsFunction(tp.AppInitializeBefore))
            tp.AppInitializeBefore();
        List = tp.ReadyListeners.slice();
        for (Index = 0; Index < List.length; Index++) {
            Listener = List[Index];
            if (Listener && tp.IsFunction(Listener.Func))
                Listener.Func.call(Listener.Context || null);
        }
        tp.ReadyListeners.length = 0;
        if (tp.IsFunction(tp.AppInitializeAfter))
            tp.AppInitializeAfter();
        if (tp.IsFunction(tp.Main))
            tp.Main();
    };

    if (document.readyState === "loading")
        document.addEventListener("DOMContentLoaded", Initialize, { once: true });
    else
        Initialize();
})();

